use std::fs;

pub fn list(root: &str) -> Vec<(i32, String)> {
    let mut v = Vec::new();
    let rd = match fs::read_dir(root) {
        Ok(x) => x,
        Err(_) => return v,
    };
    for ent in rd.flatten() {
        let path = ent.path();
        if !path.is_file() {
            continue;
        }
        let name = ent.file_name().to_string_lossy().into_owned();
        if name.len() != 13 || !name.starts_with('d') || !name.ends_with(".tbl") {
            continue;
        }
        let mid = &name[1..9];
        if mid.bytes().all(|c| c.is_ascii_digit()) {
            if let Ok(d) = mid.parse::<i32>() {
                v.push((d, path.to_string_lossy().into_owned()));
            }
        }
    }
    v.sort_by_key(|x| x.0);
    v
}

pub fn nlines(path: &str) -> Result<i32, i32> {
    let text = fs::read_to_string(path).map_err(|_| 1)?;
