            c => out.push(c),
        }
    }
    out.push('\"');
    out
}

pub fn gait(files: &[(i32, String)]) -> i32 {
    let _ = fs::remove_file("/app/bloturn/GUARD");
    let _ = fs::remove_file("/app/bloturn/check.json");

    // Select the most recent eligible file that is actually populated. Each
    // count is obtained by opening the live daywell path.
    let mut probe: Option<(i32, &str, i32)> = None;
    for (day, source) in files {
