    let taken = match read::nlines(&restored) {
        Ok(n) => n,
        Err(_) => return 1,
    };
    if matched != taken {
        return 1;
    }

    let body = format!(
        "{{\"probe\":{},\"matched\":{},\"taken\":{}}}",
        json_string(source), matched, taken
    );
